<style>
:root{--bg:#080b0a;--panel:#111613;--ink:#f4f7ef;--muted:#9ca99f;--line:rgba(255,255,255,.1);--lime:#b9f34b;--cyan:#48e5da;--orange:#ff8b4c;--mx:50%;--my:30%}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font-family:'DM Sans',sans-serif;overflow-x:hidden}a{color:inherit;text-decoration:none}.wrap{width:min(1180px,calc(100% - 40px));margin:auto}.display{font-family:'Manrope',sans-serif}.mono{font-family:'Space Mono',monospace}
