.nav{position:fixed;inset:0 0 auto;z-index:50;border-bottom:1px solid transparent;transition:.35s}.nav.scrolled{background:rgba(8,11,10,.76);backdrop-filter:blur(22px);border-color:var(--line)}.nav-in{height:78px;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:12px}.mark{position:relative;width:42px;height:42px;display:grid;place-items:center;border-radius:13px;background:var(--lime);color:#0b1108;font-weight:800;box-shadow:0 0 35px rgba(185,243,75,.2)}.mark:after{content:"";position:absolute;inset:4px;border:1px solid rgba(0,0,0,.3);border-radius:9px}.brand strong{display:block;font-size:14px}.brand small{display:block;margin-top:2px;color:var(--muted);font-size:9px;letter-spacing:.16em}.links{display:flex;gap:30px;color:#bbc4bd;font-size:13px}.links a{transition:.2s}.links a:hover{color:var(--lime)}
.btn{position:relative;display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:48px;padding:0 22px;border:1px solid var(--line);border-radius:999px;font-size:14px;font-weight:700;overflow:hidden;transition:transform .25s,border .25s,background .25s}.btn:hover{transform:translateY(-3px)}.btn-primary{color:#10140d;background:var(--lime);border-color:var(--lime);box-shadow:0 14px 38px rgba(185,243,75,.15)}.btn-primary:before{content:"";position:absolute;inset:-2px;transform:translateX(-120%) skewX(-18deg);background:linear-gradient(90deg,transparent,rgba(255,255,255,.55),transparent);transition:.65s}.btn-primary:hover:before{transform:translateX(120%) skewX(-18deg)}.btn-ghost{background:rgba(255,255,255,.04);backdrop-filter:blur(12px)}
.hero{position:relative;min-height:100vh;display:flex;align-items:center;padding:138px 0 80px}.orb{position:absolute;border-radius:50%;pointer-events:none}.orb.one{width:540px;height:540px;right:-170px;top:60px;background:radial-gradient(circle at 35% 35%,rgba(72,229,218,.24),rgba(72,229,218,.02) 52%,transparent 70%);animation:float 8s ease-in-out infinite}.orb.two{width:360px;height:360px;left:-170px;bottom:-80px;background:radial-gradient(circle,rgba(185,243,75,.15),transparent 65%);animation:float 11s ease-in-out infinite reverse}.hero-grid{display:grid;grid-template-columns:1.08fr .92fr;gap:70px;align-items:center}.eyebrow{display:inline-flex;align-items:center;gap:9px;color:var(--lime);font-size:10px;letter-spacing:.16em;text-transform:uppercase}.pulse{width:7px;height:7px;border-radius:50%;background:var(--lime);animation:pulse 1.7s infinite}.hero h1{max-width:720px;margin:23px 0 0;font-size:clamp(46px,6.3vw,88px);line-height:.98;letter-spacing:-.065em}.hero h1 span{color:transparent;-webkit-text-stroke:1px rgba(244,247,239,.55)}.lead{max-width:620px;margin:27px 0 0;color:var(--muted);font-size:17px;line-height:1.75}.actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:34px}.trust{display:flex;align-items:center;gap:17px;margin-top:38px;color:#77837a;font-size:11px}.trust-line{width:55px;height:1px;background:var(--line)}
.machine{position:relative;height:520px;perspective:1000px}.machine-frame{position:absolute;inset:35px 0 20px 35px;border:1px solid var(--line);border-radius:34px;background:linear-gradient(145deg,rgba(255,255,255,.08),rgba(255,255,255,.015));box-shadow:0 45px 100px rgba(0,0,0,.42);backdrop-filter:blur(24px);transform:rotateY(-7deg) rotateX(3deg);animation:machine 7s ease-in-out infinite}.machine-top{display:flex;justify-content:space-between;padding:25px 27px;color:var(--muted);font-size:10px;letter-spacing:.13em}.lights{display:flex;gap:7px}.lights i{width:7px;height:7px;border-radius:50%;background:#314038}.lights i:first-child{background:var(--lime);box-shadow:0 0 14px var(--lime)}.film{position:absolute;left:28px;right:28px;top:76px;height:265px;border-radius:22px;overflow:hidden;background:#090d0b;border:1px solid var(--line)}.film:before{content:"";position:absolute;inset:-100%;background:conic-gradient(from 30deg,transparent,rgba(72,229,218,.22),transparent 28%,rgba(185,243,75,.2),transparent 58%);animation:spin 9s linear infinite}.film-art{position:absolute;inset:1px;display:grid;place-items:center;border-radius:21px;background:radial-gradient(circle at 52% 42%,rgba(72,229,218,.21),transparent 30%),linear-gradient(145deg,#0e1511,#080b0a)}.film-logo{position:relative;font-size:96px;font-weight:800;letter-spacing:-.09em;color:var(--lime);filter:drop-shadow(0 0 26px rgba(185,243,75,.25));animation:logoPulse 3s ease-in-out infinite}.film-logo:after{content:"PRINT";position:absolute;left:50%;top:100%;transform:translate(-45%,-5px);font:10px 'Space Mono';letter-spacing:.56em;color:var(--cyan)}.rail{position:absolute;left:0;right:0;top:50px;height:11px;background:linear-gradient(90deg,#1d2922,#4e6457,#1d2922);box-shadow:0 4px 10px #000}.head{position:absolute;top:37px;width:92px;height:40px;border-radius:8px;background:linear-gradient(#d8ddd8,#66736b);box-shadow:0 8px 20px #000;animation:printHead 2.5s ease-in-out infinite}.machine-bottom{position:absolute;left:27px;right:27px;bottom:27px}.progress-label{display:flex;justify-content:space-between;color:var(--muted);font-size:10px}.progress{height:5px;margin-top:12px;border-radius:9px;background:#29332d;overflow:hidden}.progress span{display:block;height:100%;width:74%;background:linear-gradient(90deg,var(--lime),var(--cyan));animation:progress 4s ease-in-out infinite}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:18px}.metric{padding:13px;border-radius:13px;background:rgba(255,255,255,.045);border:1px solid var(--line)}.metric small{display:block;color:var(--muted);font-size:9px}.metric b{display:block;margin-top:5px;font-size:15px}.float-ticket{position:absolute;padding:15px 17px;border:1px solid var(--line);border-radius:15px;background:rgba(18,24,20,.82);backdrop-filter:blur(18px);box-shadow:0 20px 50px rgba(0,0,0,.3)}.float-ticket b{display:block;font-size:12px}.float-ticket small{display:block;margin-top:4px;color:var(--muted);font-size:9px}.ticket-a{right:-28px;top:2px;animation:float 5s ease-in-out infinite}.ticket-b{left:-12px;bottom:0;animation:float 6s 1s ease-in-out infinite}
.marquee{border-block:1px solid var(--line);overflow:hidden;background:var(--lime);color:#10140d;transform:rotate(-1deg) scale(1.01)}.marquee-track{display:flex;width:max-content;padding:14px 0;animation:marquee 20s linear infinite}.marquee-track span{font:700 11px 'Space Mono';letter-spacing:.14em;white-space:nowrap}.marquee-track span:after{content:"✦";margin:0 28px}
section.content{padding:125px 0}.section-head{display:flex;align-items:end;justify-content:space-between;gap:30px;margin-bottom:46px}.kicker{color:var(--lime);font-size:10px;letter-spacing:.16em;text-transform:uppercase}.section-head h2{max-width:650px;margin:12px 0 0;font-size:clamp(33px,4vw,55px);line-height:1.05;letter-spacing:-.045em}.section-head p{max-width:400px;margin:0;color:var(--muted);line-height:1.7;font-size:14px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card{position:relative;min-height:280px;padding:28px;border:1px solid var(--line);border-radius:24px;background:linear-gradient(145deg,rgba(255,255,255,.065),rgba(255,255,255,.018));overflow:hidden;transition:.45s cubic-bezier(.2,.8,.2,1)}.card:hover{transform:translateY(-10px);border-color:rgba(185,243,75,.35);box-shadow:0 35px 70px rgba(0,0,0,.24)}.card:after{content:"";position:absolute;width:180px;height:180px;right:-90px;bottom:-90px;border-radius:50%;background:var(--accent,var(--lime));filter:blur(70px);opacity:.1;transition:.4s}.card:hover:after{opacity:.24}.card-no{display:flex;align-items:center;justify-content:space-between;color:var(--muted);font-size:10px}.icon{width:43px;height:43px;display:grid;place-items:center;border-radius:13px;color:#0d120b;background:var(--accent,var(--lime));font-weight:800}.card h3{margin:68px 0 0;font-size:21px}.card p{margin:10px 0 0;color:var(--muted);line-height:1.65;font-size:14px}.flow{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--line);border-radius:26px;overflow:hidden}.step{position:relative;min-height:245px;padding:27px;border-right:1px solid var(--line);background:rgba(255,255,255,.025)}.step:last-child{border:0}.step-no{color:var(--lime);font-size:11px}.step h3{margin-top:78px;font-size:17px}.step p{color:var(--muted);font-size:13px;line-height:1.6}.step:before{content:"";position:absolute;top:63px;left:27px;width:calc(100% - 54px);height:1px;background:linear-gradient(90deg,var(--lime),transparent)}
.cta{padding:20px 0 105px}.cta-box{position:relative;padding:75px clamp(25px,7vw,85px);border-radius:34px;overflow:hidden;color:#0b1009;background:var(--lime)}.cta-box:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 85% 20%,rgba(72,229,218,.8),transparent 35%),repeating-linear-gradient(120deg,transparent 0 24px,rgba(0,0,0,.028) 24px 25px)}.cta-box>*{position:relative}.cta-box h2{max-width:760px;margin:0;font-size:clamp(38px,5.5vw,70px);line-height:1;letter-spacing:-.055em}.cta-box p{max-width:560px;line-height:1.7}.cta-box .btn{background:#0b1009;color:white;border-color:#0b1009}.footer{padding:35px 0;border-top:1px solid var(--line)}.footer-in{display:flex;align-items:center;justify-content:space-between;color:var(--muted);font-size:11px}[data-reveal]{opacity:0;transform:translateY(35px);transition:opacity .9s,transform .9s cubic-bezier(.2,.7,.2,1)}[data-reveal].visible{opacity:1;transform:none}
@keyframes float{50%{transform:translateY(-18px) rotate(2deg)}}@keyframes pulse{70%{box-shadow:0 0 0 12px rgba(185,243,75,0)}}@keyframes spin{to{transform:rotate(360deg)}}@keyframes machine{50%{transform:rotateY(2deg) rotateX(-1deg) translateY(-8px)}}@keyframes logoPulse{50%{transform:scale(1.06);filter:drop-shadow(0 0 42px rgba(185,243,75,.45))}}@keyframes printHead{0%,100%{left:5%}50%{left:72%}}@keyframes progress{50%{width:94%}}@keyframes marquee{to{transform:translateX(-50%)}}
html{scrollbar-width:thin;scrollbar-color:var(--lime) #101512}*::-webkit-scrollbar{width:12px;height:12px}*::-webkit-scrollbar-track{background:#101512}*::-webkit-scrollbar-thumb{min-height:52px;border:3px solid #101512;border-radius:999px;background:linear-gradient(180deg,var(--lime),var(--cyan));box-shadow:0 0 18px rgba(185,243,75,.25)}*::-webkit-scrollbar-thumb:hover{border-width:2px;box-shadow:0 0 24px rgba(72,229,218,.48)}*::-webkit-scrollbar-thumb:active{background:linear-gradient(180deg,var(--orange),var(--lime))}*::-webkit-scrollbar-corner{background:#101512}
@media(max-width:900px){.links{display:none}.hero-grid{grid-template-columns:1fr}.hero{padding-top:120px}.machine{height:450px;max-width:600px}.cards{grid-template-columns:1fr}.flow{grid-template-columns:1fr 1fr}.step:nth-child(2){border-right:0}.step:nth-child(-n+2){border-bottom:1px solid var(--line)}.section-head{align-items:start;flex-direction:column}.card{min-height:230px}.card h3{margin-top:45px}}@media(max-width:560px){.wrap{width:min(100% - 28px,1180px)}.nav-in{height:68px}.brand small{display:none}.nav .btn{min-height:40px;padding:0 16px}.hero h1{font-size:43px}.lead{font-size:15px}.machine{height:390px}.machine-frame{inset:25px 5px}.ticket-a{right:-4px}.ticket-b{left:-3px}.film{height:210px}.film-logo{font-size:72px}.metrics{display:none}.flow{grid-template-columns:1fr}.step{min-height:190px;border-right:0;border-bottom:1px solid var(--line)!important}.step:last-child{border-bottom:0!important}.step h3{margin-top:55px}.footer-in{align-items:flex-start;flex-direction:column;gap:16px}section.content{padding:90px 0}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important}}
